const PREPARED_RECEIPT:[u64;10]=[41, 32, 32, 0, 1, 0, 0, 0, 32, 3];
mod gpu_device;

// Formatting only: arithmetic, including quotient and product, stays on GPU.
fn word(arms:&[u8])->Result<String,String>{
    if arms.iter().any(|&a|a!=8&&a!=9){return Err("invalid device parity cell".into());}
    let end=arms.iter().rposition(|&a|a==9).map_or(0,|i|i+1);
    let mut out=String::from("⊢");
    for &a in &arms[..end]{out.push_str(if a==9{"≻⋈∈⊥∋"}else{"≻⋈∈⊤∋"});}
    out.push_str("⊙⊡⊣");Ok(out)
}
fn main()->Result<(),String>{
    if std::env::args_os().len()!=1{return Err("baked membrane accepts no instance arguments".into());}
    let trigger=Instant::now();
    let ctx=gpu_device::select()?;
    let name=ctx.name().map_err(|e|e.to_string())?;
    if !name.contains("4070"){return Err(format!("GPU 1 must be RTX 4070, found {name}"));}
    let stream=ctx.default_stream();
    let module=ctx.load_module(Ptx::from_src(PTX)).map_err(|e|format!("CUDA embedded PTX: {e}"))?;
    let kernel=module.load_function("idempotent_membrane").map_err(|e|e.to_string())?;
    let mut state=stream.clone_htod(&PREPARED_STATE).map_err(|e|e.to_string())?;
    let mut receipt=stream.clone_htod(&PREPARED_RECEIPT).map_err(|e|e.to_string())?;
    println!("device=1 native_cuda_ordinal={} name={name} uuid=GPU-9ba0eed8-e18b-02a5-7c80-ca49712e25d1\nsource={SOURCE}\ninstance_inputs=N-only baked\nproducer=GPU-source-powered-idempotent-with-SIC-Zeta\noperator=s=2e-1; s'=s^k mod N; e'=(s'+1)/2 mod N\nY_reducer=GPU powerset_bind=GPU resident_SIC_Zeta_dual=GPU reentry_residue=Belnap-B idempotent_arithmetic=GPU factor_extraction=GPU quotient=GPU exact_product=GPU",ctx.ordinal());
    println!("prepared_Y_calls={} prepared_Y_contractions={} prepared_powerset_binds={} prepared_SIC_Zeta_roundtrips={} prepared_reentry_residue_B={}",PREPARED_RECEIPT[1],PREPARED_RECEIPT[0],PREPARED_RECEIPT[2],PREPARED_RECEIPT[8],PREPARED_RECEIPT[9]);
    let mut initialize=0i32;
    let mut last_report=Instant::now();
    loop{
        let mut launch=stream.launch_builder(&kernel);
        launch.arg(&mut state).arg(&mut receipt).arg(&32u32).arg(&initialize);
        unsafe{launch.launch(LaunchConfig{grid_dim:(1,1,1),block_dim:(32,1,1),shared_mem_bytes:0})}
            .map_err(|e|e.to_string())?;
        let observed=stream.clone_dtoh(&receipt).map_err(|e|e.to_string())?;
        if initialize!=0||last_report.elapsed().as_secs()>=1||observed[3]!=0{
            println!("readout_seconds={:.9} Y_contractions={} Y_calls={} powerset_binds={} held={} restarts={} projecting={} singularities={} SIC_Zeta_roundtrips={} reentry_residue_B={} status={}",
                trigger.elapsed().as_secs_f64(),observed[0],observed[1],observed[2],observed[4],observed[5],observed[6],observed[7],observed[8],observed[9],observed[3]);
            last_report=Instant::now();
        }
        if observed[3]!=0{
            let returned=stream.clone_dtoh(&state).map_err(|e|e.to_string())?;
            for (index,label) in ["idempotent","residual","complement","divisor","quotient","exponent","initial_candidate","last_trivial_candidate","last_trivial_residual","source_power","singular_projection","SIC_Zeta_frame_residual","reentry_source_presentation","reentry_return_presentation"].iter().enumerate(){
                println!("{label}={}",word(&returned[index*WIDTH..(index+1)*WIDTH])?);
            }
            if observed[3]!=1{return Err(format!("device returned status {}",observed[3]));}
            println!("GPU_idempotency=true GPU_orthogonality=true GPU_complementary_sum=true GPU_proper_divisor=true GPU_remainder=0 GPU_exact_word_product=true GPU_paired_boundary=true\ntrigger_to_verified_factor_seconds={:.9}",trigger.elapsed().as_secs_f64());
            return Ok(());
        }
        initialize=0;
    }
}
